// FUNCTION: BFME2 0x0012B330 size=36 name=?Is_Valid_Display_Format@DX8Caps@@QAE_NHHW4WW3DFormat@@@Z evidence=N:ledger tier=B hypothesis:K
bool DX8Caps::Is_Valid_Display_Format(int width, int height, WW3DFormat format)
{
	if (MaxDisplayWidth == 0 && MaxDisplayHeight == 0) return true;
	if (width <= MaxDisplayWidth && height <= MaxDisplayHeight) return true;
	return false;
}

